460→// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
461→// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
462→type CheckpointRemoteConfig struct {
463→	Provider string // e.g., "github"
464→	Repo     string // e.g., "org/checkpoints-repo"
465→}
466→
467→// Owner returns the owner portion of the repo field (before the slash).
468→// Returns empty string if the repo field doesn't contain a slash.
469→func (c *CheckpointRemoteConfig) Owner() string {
470→	parts := strings.SplitN(c.Repo, "/", 2)
471→	if len(parts) < 2 {
472→		return ""
473→	}
474→	return parts[0]
475→}
476→
477→// GetCheckpointRemote returns the configured checkpoint remote.
478→// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
479→// Returns nil if not configured, wrong type, or missing required fields.
480→func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
481→	if s.StrategyOptions == nil {
482→		return nil
483→	}
484→	val, ok := s.StrategyOptions["checkpoint_remote"]
485→	if !ok {
486→		return nil
487→	}
488→	m, ok := val.(map[string]any)
489→	if !ok {
490→		return nil
491→	}
492→	provider, providerOK := m["provider"].(string)
493→	repo, repoOK := m["repo"].(string)
494→	if !providerOK || !repoOK || provider == "" || repo == "" {
495→		return nil
496→	}
497→	if !strings.Contains(repo, "/") {
498→		return nil
499→	}
500→	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
501→}
