549→// saveToFile saves settings to the specified file path.
550→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
551→	// Get absolute path for the file
552→	filePathAbs, err := paths.AbsPath(ctx, filePath)
553→	if err != nil {
554→		filePathAbs = filePath // Fallback to relative
555→	}
556→
557→	// Ensure directory exists
558→	dir := filepath.Dir(filePathAbs)
559→	if err := os.MkdirAll(dir, 0o750); err != nil {
560→		return fmt.Errorf("creating settings directory: %w", err)
561→	}
562→
563→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
564→	if err != nil {
565→		return fmt.Errorf("marshaling settings: %w", err)
566→	}
567→
568→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
569→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
570→		return fmt.Errorf("writing settings file: %w", err)
571→	}
572→	return nil
573→}
